<?php
require_once __DIR__.'/config.php'; require_login(); if(!fams_current_type_allows('AICS','manage_offices')){http_response_code(403);exit('Office management is not permitted.');} require_role(['admin']);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';try{
 if($action==='save'){ $id=(int)($_POST['id']??0);$name=trim((string)$_POST['name']);$short=trim((string)$_POST['short_name']);$parent=(int)($_POST['parent_id']??0)?:null;if($name===''||$short==='')throw new RuntimeException('Office name and short name are required.');if($id){$pdo->prepare('UPDATE aics_offices SET name=?,short_name=?,parent_id=? WHERE id=?')->execute([$name,$short,$parent,$id]);log_action($pdo,'UPDATE_OFFICE','Updated SWAD Office '.$name);}else{$pdo->prepare('INSERT INTO aics_offices(name,short_name,parent_id) VALUES(?,?,?)')->execute([$name,$short,$parent]);log_action($pdo,'CREATE_OFFICE','Created SWAD Office '.$name);}flash('success','Office saved.');}
 elseif($action==='toggle'){ $id=(int)$_POST['id'];$pdo->prepare('UPDATE aics_offices SET is_active=1-is_active WHERE id=?')->execute([$id]);log_action($pdo,'TOGGLE_OFFICE','Changed office active status.');flash('success','Office status updated.');}
 elseif($action==='remove'){ $id=(int)($_POST['id']??0);if($id<1)throw new RuntimeException('Invalid office.');$st=$pdo->prepare('SELECT name FROM aics_offices WHERE id=?');$st->execute([$id]);$officeName=$st->fetchColumn();if(!$officeName)throw new RuntimeException('Office not found.');$st=$pdo->prepare('SELECT (SELECT COUNT(*) FROM aics_users WHERE office_id=?) + (SELECT COUNT(*) FROM aics_assistance_records WHERE office_id=?) + (SELECT COUNT(*) FROM aics_offices WHERE parent_id=?)');$st->execute([$id,$id,$id]);if((int)$st->fetchColumn()>0)throw new RuntimeException('This office cannot be removed while it has assigned users, assistance records, or child offices. Reassign those items first.');$pdo->prepare('DELETE FROM aics_offices WHERE id=?')->execute([$id]);log_action($pdo,'REMOVE_OFFICE','Removed SWAD office '.$officeName);flash('success','Office removed.');}
}catch(Throwable $e){flash('error',$e->getMessage());}redirect('offices.php');}
$edit=null;if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM aics_offices WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}
$rows=$pdo->query("SELECT o.*,p.name parent_name,(SELECT COUNT(*) FROM aics_users u WHERE u.office_id=o.id AND u.is_active=1) workers,(SELECT COUNT(*) FROM aics_assistance_records r WHERE r.office_id=o.id) records FROM aics_offices o LEFT JOIN aics_offices p ON p.id=o.parent_id WHERE UPPER(TRIM(o.name)) NOT IN ('LPGMA','LPGMA OFFICE') AND UPPER(TRIM(o.short_name)) NOT IN ('LPGMA','LPGMA OFFICE') ORDER BY o.sort_order,o.id")->fetchAll();
$pageTitle='SWAD Offices';require __DIR__.'/partials/header.php';
?>
<div class="grid" style="grid-template-columns:1fr 1.4fr"><section class="card card-pad"><div class="section-head"><div><h2><?= $edit?'Edit Office':'Add SWAD Office'?></h2><span class="muted">Manage office assignments used by social workers.</span></div></div><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e((string)($edit['id']??0))?>"><div style="margin-bottom:14px"><label>Office Name</label><input class="input" name="name" required value="<?=e($edit['name']??'')?>"></div><div style="margin-bottom:14px"><label>Short Name</label><input class="input" name="short_name" required value="<?=e($edit['short_name']??'')?>"></div><div style="margin-bottom:14px"><label>Parent Office</label><select name="parent_id"><option value="0">None / Region Level</option><?php foreach($rows as $o): if(($edit['id']??0)==$o['id'])continue; ?><option value="<?=$o['id']?>" <?=((int)($edit['parent_id']??0)===$o['id'])?'selected':''?>><?=e($o['name'])?></option><?php endforeach; ?></select></div><button class="btn btn-primary"><?= $edit?'Save Changes':'Add Office'?></button><?php if($edit): ?> <a class="btn btn-secondary" href="offices.php">Cancel</a><?php endif; ?></form></section>
<section class="card card-pad"><div class="section-head"><div><h2>Configured Offices</h2><span class="muted"><?=count($rows)?> offices</span></div></div><div class="table-wrap"><table class="table"><thead><tr><th>Office</th><th>Parent</th><th>Social Workers</th><th>Records</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $o): ?><tr><td><div class="name"><?=e($o['name'])?></div><?php if(trim((string)$o['short_name'])!=='' && mb_strtolower(trim((string)$o['short_name']))!==mb_strtolower(trim((string)$o['name']))): ?><div class="sub"><?=e($o['short_name'])?></div><?php endif; ?></td><td><?=e($o['parent_name']??'Region Level')?></td><td><?=number_format((int)$o['workers'])?></td><td><?=number_format((int)$o['records'])?></td><td><span class="badge <?=$o['is_active']?'valid':'invalid'?>"><?=$o['is_active']?'ACTIVE':'INACTIVE'?></span></td><td><div class="office-row-actions"><a class="fams-icon-action fams-icon-action-edit office-icon-action" href="offices.php?edit=<?=$o['id']?>" title="Edit office" aria-label="Edit office"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M4 16.5V20h3.5L19 8.5 15.5 5 4 16.5Z"/><path d="m13.8 6.7 3.5 3.5"/></svg></a> <form style="display:inline" method="post" data-confirm="Change this office status?"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$o['id']?>"><button class="fams-icon-action fams-icon-action-toggle office-icon-action" title="<?= $o['is_active']?'Disable office':'Enable office'?>" aria-label="<?= $o['is_active']?'Disable office':'Enable office'?>"><?= $o['is_active']?'<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><circle cx="12" cy="12" r="9"/><path d="m5.6 5.6 12.8 12.8"/></svg>':'<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="m5 12.5 4.2 4.2L19 7"/></svg>'?></button></form> <form style="display:inline" method="post" data-confirm="Permanently remove this office? Removal is allowed only when no users, records, or child offices depend on it."><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="id" value="<?=$o['id']?>"><button class="fams-icon-action fams-icon-action-delete office-icon-action" title="Remove office" aria-label="Remove office"><svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M4 7h16M9 7V4h6v3m-9 0 1 13h10l1-13M10 11v5m4-5v5"/></svg></button></form></div></td></tr><?php endforeach; ?></tbody></table></div></section></div>
<?php require __DIR__.'/partials/footer.php'; ?>
